#include <stddef.h>
#include <stdint.h>
#define MAX_TEXT 24
static uint16_t mul16(uint16_t a,uint16_t b){uint64_t x=a? a:65536u,y=b?b:65536u,z=(x*y)%65537u;return z==65536u?0:(uint16_t)z;}
static void expand(const uint8_t *key,uint16_t z[52]){uint16_t s[8];for(size_t i=0;i<8;++i)s[i]=(uint16_t)(((uint16_t)key[2*i]<<8)|key[2*i+1]);for(size_t off=0;off<52;off+=8){size_t n=52-off<8?52-off:8;for(size_t i=0;i<n;++i)z[off+i]=s[i];uint16_t r[8];for(size_t i=0;i<8;++i)r[i]=(uint16_t)((s[(i+1)&7]<<9)|(s[(i+2)&7]>>7));for(size_t i=0;i<8;++i)s[i]=r[i];}}
static void encrypt(const uint16_t z[52],const uint8_t in[8],uint8_t out[8]){uint16_t x1=(uint16_t)((in[0]<<8)|in[1]),x2=(uint16_t)((in[2]<<8)|in[3]),x3=(uint16_t)((in[4]<<8)|in[5]),x4=(uint16_t)((in[6]<<8)|in[7]);for(size_t r=0;r<8;++r){const uint16_t*k=z+6*r;uint16_t a=mul16(x1,k[0]),b=(uint16_t)(x2+k[1]),c=(uint16_t)(x3+k[2]),d=mul16(x4,k[3]);uint16_t p=mul16((uint16_t)(a^c),k[4]),q=mul16((uint16_t)((b^d)+p),k[5]),t=(uint16_t)(p+q);x1=(uint16_t)(a^q);x2=(uint16_t)(c^q);x3=(uint16_t)(b^t);x4=(uint16_t)(d^t);}uint16_t y[4]={mul16(x1,z[48]),(uint16_t)(x3+z[49]),(uint16_t)(x2+z[50]),mul16(x4,z[51])};for(size_t i=0;i<4;++i){out[2*i]=(uint8_t)(y[i]>>8);out[2*i+1]=(uint8_t)y[i];}}
int64_t idea_cfb64(const int64_t*v,size_t n,uint8_t*out,size_t cap){if(!v||n<27||n>51)return -1;int64_t mode=v[0],lv=v[1];if(mode<0||mode>1||lv<1||lv>MAX_TEXT||n!=26+(size_t)lv)return -1;uint8_t key[16],iv[8],text[MAX_TEXT],result[MAX_TEXT];for(size_t i=0;i<16;++i){if(v[2+i]<0||v[2+i]>255)return -1;key[i]=(uint8_t)v[2+i];}for(size_t i=0;i<8;++i){if(v[18+i]<0||v[18+i]>255)return -1;iv[i]=(uint8_t)v[18+i];}for(size_t i=0;i<(size_t)lv;++i){if(v[26+i]<0||v[26+i]>255)return -1;text[i]=(uint8_t)v[26+i];}uint16_t z[52];expand(key,z);for(size_t pos=0;pos<(size_t)lv;pos+=8){uint8_t stream[8];encrypt(z,iv,stream);size_t take=(size_t)lv-pos<8?(size_t)lv-pos:8;for(size_t j=0;j<take;++j){result[pos+j]=(uint8_t)(text[pos+j]^stream[j]);iv[j]=mode==0?result[pos+j]:text[pos+j];}}if(!out||cap<(size_t)lv)return -2;for(size_t i=0;i<(size_t)lv;++i)out[i]=result[i];return lv;}
